const DAY = 24 * 60 * 60 * 1000;
const WEEK = 7 * DAY;

// Temporary storage while the bot is running.
const reminders = [];

function addReminder(userId, message, time, repeat = "none") {
  const reminder = {
    id: `${Date.now()}-${Math.random()}`,
    userId,
    message,
    nextRun: new Date(time).getTime(),
    repeat,
    history: [],
    completedAt: null,
  };

  if (!Number.isFinite(reminder.nextRun)) {
    throw new Error("Invalid reminder date");
  }

  if (!["none", "daily", "weekly"].includes(repeat)) {
    throw new Error("Invalid repeat option");
  }

  reminders.push(reminder);
  return reminder;
}

function getUpcomingReminders(userId) {
  return reminders.filter(
    (reminder) =>
      reminder.userId === userId &&
      reminder.nextRun !== null
  );
}

function getPastReminders(userId) {
  return reminders
    .filter((reminder) => reminder.userId === userId)
    .flatMap((reminder) => [
      ...reminder.history.map((time) => ({
        message: reminder.message,
        time,
        status: "sent",
      })),
      ...(reminder.completedAt
        ? [
            {
              message: reminder.message,
              time: reminder.completedAt,
              status: "done",
            },
          ]
        : []),
    ]);
}

function markReminderDone(userId, reminderId) {
  const reminder = reminders.find(
    (item) =>
      item.id === reminderId &&
      item.userId === userId &&
      item.nextRun !== null
  );

  if (!reminder) return false;

  reminder.nextRun = null;
  reminder.completedAt = Date.now();
  return true;
}

function markReminderFired(reminder) {
  if (reminder.nextRun === null) return;

  reminder.history.push(reminder.nextRun);

  if (reminder.repeat === "daily") {
    reminder.nextRun += DAY;
  } else if (reminder.repeat === "weekly") {
    reminder.nextRun += WEEK;
  } else {
    reminder.nextRun = null;
  }
}

function getAllReminders() {
  return reminders;
}

module.exports = {
  addReminder,
  getUpcomingReminders,
  getPastReminders,
  markReminderDone,
  markReminderFired,
  getAllReminders,
};

import { expect } from "chai";
import ping from "../src/commands/ping";
import testwelcome from "../src/commands/testwelcome";
import reminders from "../src/commands/reminders";
import reminderStore from "../src/helpers/reminderStore";
import { getWelcomeMessage } from "../src/events/guildMemberAdd";

// Minimal stand-in for a Discord interaction: records what the command replies.
const fakeInteraction = ({ user, optionUser = null, ping = 42 }) => {
  const replies = [];
  return {
    replies,
    user,
    client: { ws: { ping } },
    options: { getUser: () => optionUser },
    reply: async (message) => replies.push(message),
  };
};

describe("slash commands", () => {
  it("each command has a name and description", () => {
    for (const command of [ping, testwelcome, reminders]) {
      const data = command.data.toJSON();
      expect(data.name).to.be.a("string").and.not.empty;
      expect(data.description).to.be.a("string").and.not.empty;
    }
  });

  it("/ping replies with the latency", async () => {
    const interaction = fakeInteraction({ user: { id: "1" }, ping: 57 });
    await ping.execute(interaction);
    expect(interaction.replies[0]).to.include("57 ms");
  });

  it("/testwelcome sends the join welcome for the caller", async () => {
    const interaction = fakeInteraction({ user: { id: "111" } });
    await testwelcome.execute(interaction);
    expect(interaction.replies[0]).to.deep.equal(getWelcomeMessage("111"));
  });

  it("/testwelcome welcomes the chosen user when one is given", async () => {
    const interaction = fakeInteraction({
      user: { id: "111" },
      optionUser: { id: "222" },
    });
    await testwelcome.execute(interaction);
    expect(interaction.replies[0].content).to.include("<@222>");
  });

  it("/reminders shows a button and refreshes the list when clicked", async () => {
    const userId = "reminders-button-test";
    const reminder = reminderStore.addReminder(
      userId,
      "Review architecture",
      Date.now() + 60000
    );

    let listReply;
    await reminders.execute({
      user: { id: userId },
      reply: async (payload) => {
        listReply = payload;
      },
    });

    expect(listReply.content).to.include("Review architecture");
    expect(listReply.ephemeral).to.equal(true);
    expect(listReply.components).to.have.length(1);

    const button = listReply.components[0].toJSON().components[0];
    expect(button.custom_id).to.include(`reminders:done:${reminder.id}`);

    let updatedReply;
    await reminders.handleButton({
      customId: button.custom_id,
      user: { id: userId },
      update: async (payload) => {
        updatedReply = payload;
      },
    });

    expect(updatedReply.content).to.include("No upcoming reminders.");
    expect(updatedReply.content).to.include("Marked done");
    expect(reminderStore.getUpcomingReminders(userId)).to.have.length(0);
  });
});

import { SlashCommandBuilder } from "discord.js";

const command = {
  data: new SlashCommandBuilder()
    .setName("ping")
    .setDescription("Check that the bot is online and see its response time."),
  async execute(interaction) {
    /*
      Health check: replies with the gateway latency so the team can
      confirm the bot is running in a server.
    */
    const latency = Math.round(interaction.client.ws.ping);
    await interaction.reply(`Pong! Bot is online (latency ${latency} ms).`);
  },
};

export default command;

import { SlashCommandBuilder } from "discord.js";
import { getWelcomeMessage } from "../events/guildMemberAdd";

const command = {
  data: new SlashCommandBuilder()
    .setName("testwelcome")
    .setDescription("Show the welcome message the bot sends when someone joins.")
    .addUserOption((option) =>
      option
        .setName("user")
        .setDescription("Who to welcome (defaults to you)")
        .setRequired(false)
    ),
  async execute(interaction) {
    /*
      Sends the same message as the guildMemberAdd event, so the welcome
      can be tested without someone leaving and rejoining the server.
    */
    const user = interaction.options.getUser("user") ?? interaction.user;
    await interaction.reply(getWelcomeMessage(user.id));
  },
};

export default command;

import { EmbedBuilder, userMention } from "discord.js";

const CHANNEL_NAME = process.env.CHANNEL_NAME;
const MEME_URL = process.env.MEME_URL || "";

const event = {
  name: "guildMemberAdd",
  async execute(member) {
    const channel = member.guild.channels.cache.find(
      (channel) => channel.name === CHANNEL_NAME
    );

    /*
      TODO: Change getWelcomeMessage to getWelcomeMessageWithMeme to send a meme to welcome your user.
    */
    const welcomeMessage = await getWelcomeMessage(member.id);
    channel.send(welcomeMessage);
  },
};

export const getWelcomeMessage = (userId) => {
  /*
    this function returns a welcome message.
    Play around with the code here and customise the welcome message.
  */
  return {
    content: `Welcome ${userMention(userId)},
    Hope you have great time here!
  `,
  };
};

//
const getWelcomeMessageWithMeme = async (userId) => {
  /*
    this function returns a welcome message with a meme.
    Play around with the code here and customise the welcome message.

    TODO: Change this function to return different welcome message with a meme everytime a new user joins.
  */
  const meme = await getMeme();

  return {
    content: `Welcome ${userMention(userId)},
    Here's a meme for you to enjoy!`,
    embeds: [meme],
  };
};

const getMeme = async () => {
  /*
    this function returns a meme.

    TODO: change this function to return a different meme randomly everytime a new user joins.
  */
  return new EmbedBuilder().setImage(MEME_URL);
};

export default event;

import {
  ActionRowBuilder,
  ButtonBuilder,
  ButtonStyle,
  SlashCommandBuilder,
} from "discord.js";
import reminderStore from "../helpers/reminderStore.js";

const { getUpcomingReminders, getPastReminders, markReminderDone } = reminderStore;
const REMINDERS_PER_PAGE = 4;

function createReply(userId, requestedPage = 0) {
  const upcoming = getUpcomingReminders(userId);
  const past = getPastReminders(userId);
  const pageCount = Math.max(1, Math.ceil(upcoming.length / REMINDERS_PER_PAGE));
  const page = Math.min(Math.max(0, requestedPage), pageCount - 1);
  const pageReminders = upcoming.slice(
    page * REMINDERS_PER_PAGE,
    (page + 1) * REMINDERS_PER_PAGE
  );

  const upcomingText = pageReminders.length
    ? pageReminders
        .map(
          (reminder) =>
            `- ${reminder.message} (Next: ${new Date(reminder.nextRun).toLocaleString()})`
        )
        .join("\n")
    : "No upcoming reminders.";

  const pastText = past.length
    ? past
        .map(
          (reminder) =>
            `- ${reminder.message} (${reminder.status === "done" ? "Marked done" : "Sent"}: ${new Date(reminder.time).toLocaleString()})`
        )
        .join("\n")
    : "No past reminders.";

  const components = pageReminders.map((reminder) =>
    new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`reminders:done:${reminder.id}:${page}`)
        .setLabel("Mark done")
        .setStyle(ButtonStyle.Success)
    )
  );

  if (pageCount > 1) {
    components.push(
      new ActionRowBuilder().addComponents(
        new ButtonBuilder()
          .setCustomId(`reminders:page:${page - 1}`)
          .setLabel("Previous")
          .setStyle(ButtonStyle.Secondary)
          .setDisabled(page === 0),
        new ButtonBuilder()
          .setCustomId(`reminders:page:${page + 1}`)
          .setLabel("Next")
          .setStyle(ButtonStyle.Secondary)
          .setDisabled(page === pageCount - 1)
      )
    );
  }

  return {
    content: `**Upcoming Reminders** (${page + 1}/${pageCount})\n${upcomingText}\n\n**Past Reminders**\n${pastText}`,
    components,
    ephemeral: true,
  };
}

const command = {
  data: new SlashCommandBuilder()
    .setName("reminders")
    .setDescription("View your upcoming and past reminders"),

  async execute(interaction) {
    await interaction.reply(createReply(interaction.user.id));
  },

  async handleButton(interaction) {
    const [namespace, action, value, pageValue] = interaction.customId.split(":");
    if (namespace !== "reminders") return;

    const userId = interaction.user.id;

    if (action === "done") {
      const completed = markReminderDone(userId, value);

      if (!completed) {
        await interaction.reply({
          content: "That reminder is no longer active or does not belong to you.",
          ephemeral: true,
        });
        return;
      }

      await interaction.update(createReply(userId, Number(pageValue)));
      return;
    }

    if (action === "page") {
      await interaction.update(createReply(userId, Number(value)));
    }
  },
};

