import { expect } from "chai";
import { parseOffsets, parseDateInZone, buildReminderTimes } from "../src/helpers/reminderTime";
import remind from "../src/commands/reminder";
import store from "../src/helpers/reminderStore.js";

const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
const NOW = Date.UTC(2026, 10, 1, 12, 0); // 2026-11-01 12:00 UTC

describe("reminder times", () => {
  it("reads a before list largest first", () => {
    const offsets = parseOffsets("30m, 1d,2h");
    expect(offsets.map((o) => o.ms)).to.deep.equal([DAY, 2 * HOUR, 30 * 60 * 1000]);
    expect(offsets[0].label).to.equal("1 day");
  });

  it("rejects a bad before entry", () => {
    expect(() => parseOffsets("1d, soon")).to.throw("soon");
    expect(() => parseOffsets("1m,2m,3m,4m,5m,6m")).to.throw("at most");
  });

  it("reads a Pacific date in daylight time and standard time", () => {
    // PDT is UTC-7, PST is UTC-8.
    expect(parseDateInZone("2026-10-30 14:30")).to.equal(Date.UTC(2026, 9, 30, 21, 30));
    expect(parseDateInZone("2026-11-05 09:00")).to.equal(Date.UTC(2026, 10, 5, 17, 0));
  });

  it("rejects badly formed or impossible dates", () => {
    expect(() => parseDateInZone("11/05/2026 9am")).to.throw("YYYY-MM-DD");
    expect(() => parseDateInZone("2026-02-30 10:00")).to.throw("not a real date");
    expect(() => parseDateInZone("2026-11-05 14:60")).to.throw("not a real date");
  });

  it("rejects a time skipped by spring forward, keeps the first fall-back hour", () => {
    expect(() => parseDateInZone("2027-03-14 02:30")).to.throw("spring forward");
    expect(parseDateInZone("2026-11-01 01:30")).to.equal(Date.UTC(2026, 10, 1, 8, 30));
  });

  it("drops repeated before times and caps their size", () => {
    expect(parseOffsets("1d, 24h, 1d")).to.have.length(1);
    expect(() => parseOffsets("99999d")).to.throw("not a time");
  });

  it("rejects times too far ahead instead of overflowing", () => {
    expect(() => buildReminderTimes({ amount: 200000000, unit: "day", now: NOW })).to.throw("5 years");
  });

  it("schedules a time from now plus each before time", () => {
    const plan = buildReminderTimes({ amount: 2, unit: "day", before: "1d, 1h", now: NOW });
    expect(plan.eventTime).to.equal(NOW + 2 * DAY);
    expect(plan.times.map((t) => t.time)).to.deep.equal([NOW + DAY, NOW + 2 * DAY - HOUR, NOW + 2 * DAY]);
    expect(plan.times.at(-1).label).to.equal("at the event");
  });

  it("skips before times that have already passed", () => {
    const plan = buildReminderTimes({ amount: 2, unit: "hour", before: "1d, 1h", now: NOW });
    expect(plan.skipped).to.deep.equal(["1 day"]);
    expect(plan.times).to.have.length(2);
  });

  it("needs exactly one of a date or an amount and unit", () => {
    expect(() => buildReminderTimes({ now: NOW })).to.throw("Give a date");
    expect(() => buildReminderTimes({ amount: 1, unit: "day", date: "2026-11-05 09:00", now: NOW })).to.throw("not both");
    expect(() => buildReminderTimes({ amount: 1, now: NOW })).to.throw("both an amount and a unit");
    expect(() => buildReminderTimes({ date: "2020-01-01 09:00", now: NOW })).to.throw("already passed");
  });
});

describe("/reminder", () => {
  const fakeInteraction = (userId, values) => {
    const replies = [];
    const get = (name) => (values[name] === undefined ? null : values[name]);
    return {
      replies,
      user: { id: userId },
      options: { getString: get, getInteger: get },
      reply: async (message) => replies.push(message),
    };
  };

  it("saves one reminder per time and lists them", async () => {
    const interaction = fakeInteraction("remind-test", { message: "Exam", amount: 3, unit: "day", before: "1d, 2h" });
    await remind.execute(interaction);

    const saved = store.getUpcomingReminders("remind-test");
    expect(saved.map((r) => r.message)).to.deep.equal(["Exam (1 day before)", "Exam (2 hours before)", "Exam"]);
    expect(interaction.replies[0].content).to.include("I'll DM you");
  });

  it("explains a bad input and saves nothing", async () => {
    const interaction = fakeInteraction("remind-bad", { message: "Exam", date: "tomorrow" });
    await remind.execute(interaction);

    expect(store.getUpcomingReminders("remind-bad")).to.have.length(0);
    expect(interaction.replies[0].content).to.include("YYYY-MM-DD");
  });
});
// Time math for /reminder: when the event is, and when to send each reminder.

const UNIT_MS = {
  second: 1000,
  minute: 60 * 1000,
  hour: 60 * 60 * 1000,
  day: 24 * 60 * 60 * 1000,
};

// Short letters accepted in the "before" list, e.g. "1d, 2h, 30m".
const SHORT_UNITS = { s: "second", m: "minute", h: "hour", d: "day" };

export const MAX_OFFSETS = 5;
export const DEFAULT_TIME_ZONE = "America/Los_Angeles";
const MAX_AHEAD_MS = 5 * 366 * UNIT_MS.day;

export function durationMs(amount, unit) {
  if (!UNIT_MS[unit]) throw new Error(`Unknown unit: ${unit}`);
  return amount * UNIT_MS[unit];
}

// Reads a list like "1d, 2h, 30m" into [{ ms, label }], largest first.
export function parseOffsets(text) {
  if (!text || !text.trim()) return [];

  const parts = text.split(",").map((part) => part.trim()).filter(Boolean);
  if (parts.length > MAX_OFFSETS) {
    throw new Error(`Use at most ${MAX_OFFSETS} times in "before".`);
  }

  const offsets = parts.map((part) => {
    const match = /^(\d{1,4})\s*([smhd])$/i.exec(part);
    if (!match || Number(match[1]) < 1) {
      throw new Error(`"${part}" is not a time like 30m, 2h or 1d.`);
    }
    const amount = Number(match[1]);
    const unit = SHORT_UNITS[match[2].toLowerCase()];
    return {
      ms: durationMs(amount, unit),
      label: `${amount} ${unit}${amount === 1 ? "" : "s"}`,
    };
  });

  // "1d, 24h" mean the same time, so keep only one of them.
  const unique = offsets.filter((offset, i) => offsets.findIndex((o) => o.ms === offset.ms) === i);
  return unique.sort((a, b) => b.ms - a.ms);
}

// How far the time zone is ahead of UTC at a given instant, in ms.
function zoneOffsetMs(instant, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(instant));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  const asUtc = Date.UTC(get("year"), get("month") - 1, get("day"), get("hour"), get("minute"), get("second"));
  return asUtc - instant;
}

// Reads "YYYY-MM-DD HH:MM" as a wall-clock time in the given zone.
export function parseDateInZone(text, timeZone = DEFAULT_TIME_ZONE) {
  const match = /^(\d{4})-(\d{2})-(\d{2})[ T](\d{1,2}):(\d{2})$/.exec((text || "").trim());
  if (!match) {
    throw new Error('Write the date as "YYYY-MM-DD HH:MM", for example 2026-11-05 14:30.');
  }

  const [year, month, day, hour, minute] = match.slice(1).map(Number);
  const wallClock = Date.UTC(year, month - 1, day, hour, minute);

  // Rejects dates like 2026-02-30 that Date.UTC would quietly roll over.
  const check = new Date(wallClock);
  if (check.getUTCMonth() !== month - 1 || check.getUTCDate() !== day || hour > 23 || minute > 59) {
    throw new Error(`"${text}" is not a real date and time.`);
  }

  // Guess with the offset at the wall-clock time, then correct once for DST.
  let instant = wallClock - zoneOffsetMs(wallClock, timeZone);
  instant = wallClock - zoneOffsetMs(instant, timeZone);

  // Times skipped when clocks spring forward (e.g. 2:30 AM) never happen.
  if (instant + zoneOffsetMs(instant, timeZone) !== wallClock) {
    throw new Error(`${text} doesn't exist because clocks spring forward then. Pick another time.`);
  }
  return instant;
}

// Works out the event time and every reminder time from the command options.
export function buildReminderTimes({ amount, unit, date, before, now = Date.now(), timeZone = DEFAULT_TIME_ZONE }) {
  const hasDuration = amount != null || unit != null;
  if (hasDuration && date) throw new Error("Pick either a date or an amount and unit, not both.");
  if (!hasDuration && !date) throw new Error("Give a date, or an amount and unit.");
  if (hasDuration && (amount == null || unit == null)) throw new Error("Give both an amount and a unit.");

  const eventTime = date ? parseDateInZone(date, timeZone) : now + durationMs(amount, unit);
  if (eventTime <= now) throw new Error("That time has already passed.");
  if (eventTime > now + MAX_AHEAD_MS) throw new Error("Pick a time within the next 5 years.");

  const times = [];
  const skipped = [];
  for (const offset of parseOffsets(before)) {
    const time = eventTime - offset.ms;
    if (time <= now) skipped.push(offset.label);
    else times.push({ time, label: `${offset.label} before` });
  }
  times.push({ time: eventTime, label: "at the event" });

  return { eventTime, times, skipped };
}
import { SlashCommandBuilder, MessageFlags } from "discord.js";
import reminderStore from "../helpers/reminderStore.js";
import { buildReminderTimes, MAX_OFFSETS } from "../helpers/reminderTime.js";

const { addReminder } = reminderStore;

// Discord renders <t:...> in each viewer's own time zone.
const discordTime = (ms) => `<t:${Math.floor(ms / 1000)}:f> (<t:${Math.floor(ms / 1000)}:R>)`;

const command = {
  data: new SlashCommandBuilder()
    .setName("reminder")
    .setDescription("Set a reminder for a time from now or a date, with extra reminders before it.")
    .addStringOption((option) =>
      option
        .setName("message")
        .setDescription("What should I remind you about?")
        .setMaxLength(1500)
        .setRequired(true)
    )
    .addIntegerOption((option) =>
      option
        .setName("amount")
        .setDescription("How many units of time from now (use with unit)")
        .setMinValue(1)
    )
    .addStringOption((option) =>
      option
        .setName("unit")
        .setDescription("The unit of time (use with amount)")
        .addChoices(
          { name: "Seconds", value: "second" },
          { name: "Minutes", value: "minute" },
          { name: "Hours", value: "hour" },
          { name: "Days", value: "day" }
        )
    )
    .addStringOption((option) =>
      option
        .setName("date")
        .setDescription("Event date and time, Pacific: YYYY-MM-DD HH:MM (instead of amount and unit)")
    )
    .addStringOption((option) =>
      option
        .setName("before")
        .setDescription(`Extra reminders before the event, up to ${MAX_OFFSETS}, e.g. 1d, 2h, 30m`)
    ),

  async execute(interaction) {
    const message = interaction.options.getString("message", true);

    let plan;
    try {
      plan = buildReminderTimes({
        amount: interaction.options.getInteger("amount"),
        unit: interaction.options.getString("unit"),
        date: interaction.options.getString("date"),
        before: interaction.options.getString("before"),
      });
    } catch (error) {
      await interaction.reply({ content: error.message, flags: MessageFlags.Ephemeral });
      return;
    }

    for (const { time, label } of plan.times) {
      const text = label === "at the event" ? message : `${message} (${label})`;
      addReminder(interaction.user.id, text, time);
    }

    const lines = plan.times.map(({ time, label }) => `- ${discordTime(time)}, ${label}`);
    if (plan.skipped.length) {
      lines.push(`Skipped ${plan.skipped.join(", ")} before, since that time already passed.`);
    }

    await interaction.reply({
      content: `Reminder set for "${message}". I'll DM you:\n${lines.join("\n")}`,
      flags: MessageFlags.Ephemeral,
    });
  },
};

export default command;
